/* Pure assignment model. Contexts are generated by the independent matrix checker. */
(function (root) {
  class ContextModel {
    constructor(profile) {
      this.profile = profile;
      this.incident = new Map(profile.points.map(p => [p, []]));
      profile.lines.forEach((line, i) => line.slice(0,3).forEach(p => this.incident.get(p).push(i)));
      this.reset();
    }
    reset() {
      this.signs = new Int8Array(4 ** this.profile.qubits).fill(1);
      this.profile.negative.forEach(p => {this.signs[p] = -1;});
      this.recount();
    }
    recount() {
      this.bad = this.profile.lines.map(([u,v,w,s]) => this.signs[u]*this.signs[v]*this.signs[w] !== s);
      this.violations = this.bad.filter(Boolean).length;
    }
    flip(p) {
      if (!this.incident.has(p)) throw new Error('Unknown observable');
      this.signs[p] *= -1;
      for (const i of this.incident.get(p)) {
        this.violations += this.bad[i] ? -1 : 1;
        this.bad[i] = !this.bad[i];
      }
    }
    randomize(random = Math.random) {
      this.profile.points.forEach(p => {this.signs[p] = random() < .5 ? -1 : 1;});
      this.recount();
    }
    bestFlip() {
      let best = 0, point = null;
      for (const p of this.profile.points) {
        let delta = 0;
        for (const i of this.incident.get(p)) delta += this.bad[i] ? -1 : 1;
        if (delta < best) { best = delta; point = p; }
      }
      if (point !== null) this.flip(point);
      return point;
    }
    serialize() {
      let hex = '';
      for (let nibble = this.signs.length/4 - 1; nibble >= 0; nibble--) {
        let v = 0;
        for (let bit=0;bit<4;bit++) if (this.signs[nibble*4+bit]<0) v |= 1<<bit;
        hex += v.toString(16);
      }
      return `${this.profile.qubits} ${this.profile.family} ${this.violations}\n${hex}\n`;
    }
  }
  root.ContextModel = ContextModel;
  if (typeof module !== 'undefined') module.exports = { ContextModel };
})(globalThis);
